import type { CoreFrame } from "./cores/driver";
import { EPILOGUE, PRELUDE } from "./cores/prelude";
import type { CoreConcept } from "./cores/types";
import { SDF_H, SDF_PAD, SDF_RANGE, SDF_S, SDF_W, buildMarkSdf } from "./coreSdf";

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

export interface CoreGL {
  render(frame: CoreFrame, light: boolean): void;
  resize(cssSize: number, dpr: number): void;
  dispose(): void;
