/** How wide the Y is inside the orb, in sphere units (sphere radius = 1). */
const LOGO_WIDTH = 1.16;
/** The mark spans 900 design units (x 40..940), centred on (490, 300). */
const DPU = 900 / LOGO_WIDTH;

let sdfCache: Uint8Array | null = null;

export function createCoreGL(canvas: HTMLCanvasElement, concept: CoreConcept): CoreGL | null {
  const gl = canvas.getContext("webgl", { premultipliedAlpha: true, alpha: true, antialias: false });
  if (!gl) return null;

