    const s = gl.createShader(type);
    if (!s) return null;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      console.error(`[core:${concept.id}] shader error\n${gl.getShaderInfoLog(s)}`);
      return null;
    }
    return s;
  };
  const vs = compile(gl.VERTEX_SHADER, VERT);
  const fs = compile(gl.FRAGMENT_SHADER, PRELUDE + "\n" + concept.frag + "\n" + EPILOGUE);
  if (!vs || !fs) return null;
