  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    console.error(`[core:${concept.id}] link error\n${gl.getProgramInfoLog(prog)}`);
    return null;
