    time: u("uTime"),
    swirl: u("uSwirl"),
    tilt: u("uTilt"),
    tiltX: u("uTiltX"),
    energy: u("uEnergy"),
    pulse: u("uPulse"),
    kick: u("uKick"),
    impulse: u("uImpulse"),
    kicks: u("uKicks"),
    waveR: u("uWaveR"),
    waveS: u("uWaveS"),
    waveAge: u("uWaveAge"),
    waveSeed: u("uWaveSeed"),
