import type { CoreConcept } from "../types";

/**
 * Holo HUD — a flat sci-fi targeting display: hairline rings, ticks, segmented arcs and data
 * rings turning at their own speeds, a trailing radar sweep, and the Y as a scanlined hologram.
 * Typing fires radar pings, glitches the display, ticks the counters and locks the rings together.
 */
export const holo: CoreConcept = {
  id: "holo",
  name: "Holo HUD",
  kind: "2D",
  tagline: "Holographic targeting display",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 2.0,
  frag: /* glsl */ `
const vec3 H_CYAN = vec3(0.10, 0.86, 1.00);
const vec3 H_ICE = vec3(0.70, 0.96, 1.00);
const vec3 H_BLUE = vec3(0.24, 0.50, 1.00);
const vec3 H_VIOLET = vec3(0.60, 0.36, 1.00);
const vec3 H_MAG = vec3(0.96, 0.26, 0.92);

float hLine(float d, float px, float w) { return clamp(0.5 * w + 0.5 - abs(d) / px, 0.0, 1.0); }
float hFill(float sd, float px) { return clamp(0.5 - sd / px, 0.0, 1.0); }
float hMaxc(vec3 c) { return max(max(c.r, c.g), c.b); }
vec3 hInk(vec3 c) { return mix(c * c * 0.7, vec3(0.03, 0.10, 0.36), 0.3); }

// Emissive mark: light on the dark theme, saturated ink on the light theme.
void hEmit(inout vec4 S, vec3 c, float a) {
  if (uLight > 0.5) {
    float k = clamp(a, 0.0, 1.0);
    S = S * (1.0 - k) + vec4(hInk(c) * k, k);
  } else {
    S.rgb += c * a;
  }
}
void hGlow(inout vec4 S, vec3 c, float a) {
  if (uLight > 0.5) {
    float k = clamp(a * 0.4, 0.0, 1.0);
    S = S * (1.0 - k) + vec4(hInk(c) * k, k);
  } else {
    S.rgb += c * a;
  }
}
void hOver(inout vec4 S, vec3 c, float a) { S = S * (1.0 - a) + vec4(c * a, a); }

// Annular sector pattern: N segments each filling 'fill' of its cell, rotated by rot (turns).
float hSegSd(float r, float t, float r0, float r1, float N, float fill, float rot) {
  float u = fract((t - rot) * N);
  float sa = (abs(u - 0.5) - 0.5 * fill) / N * TAU * r;
  return max(sa, max(r0 - r, r - r1));
}
float hTicks(float r, float t, float r0, float r1, float N, float rot, float px) {
  float u = fract((t - rot) * N);
  float d = (u - 0.5) / N * TAU * r;
  return hLine(d, px, 1.15) * hFill(max(r0 - r, r - r1), px);
}
// Phase-lock a ring with N-fold symmetry toward angle L by amount k (smooth, never jumps).
float hLock(float rot, float L, float N, float k) {
  return rot + k * sin(TAU * N * (L - rot)) / (TAU * N);
}

float hSegMask(float d) {
  if (d < 0.5) return 63.0;
  if (d < 1.5) return 6.0;
  if (d < 2.5) return 91.0;
  if (d < 3.5) return 79.0;
  if (d < 4.5) return 102.0;
  if (d < 5.5) return 109.0;
  if (d < 6.5) return 125.0;
  if (d < 7.5) return 7.0;
  if (d < 8.5) return 127.0;
  return 111.0;
}
float hBit(float m, float k) { return mod(floor(m / k + 0.001), 2.0); }
float hSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
// One seven-segment digit in a w x h box (origin bottom-left). Returns (lit, all) coverage.
vec2 hDigit(vec2 p, float d, float w, float h, float px) {
  p.x -= p.y * 0.18;
  float m = hSegMask(d);
  float g = w * 0.16;
  float hh = h * 0.5;
  float lit = 0.0;
  float all = 0.0;
  float s;
  s = hLine(hSeg(p, vec2(g, h), vec2(w - g, h)), px, 1.4); lit = max(lit, s * hBit(m, 1.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(w, hh + g), vec2(w, h - g)), px, 1.4); lit = max(lit, s * hBit(m, 2.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(w, g), vec2(w, hh - g)), px, 1.4); lit = max(lit, s * hBit(m, 4.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(g, 0.0), vec2(w - g, 0.0)), px, 1.4); lit = max(lit, s * hBit(m, 8.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(0.0, g), vec2(0.0, hh - g)), px, 1.4); lit = max(lit, s * hBit(m, 16.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(0.0, hh + g), vec2(0.0, h - g)), px, 1.4); lit = max(lit, s * hBit(m, 32.0)); all = max(all, s);
  s = hLine(hSeg(p, vec2(g, hh), vec2(w - g, hh)), px, 1.4); lit = max(lit, s * hBit(m, 64.0)); all = max(all, s);
  return vec2(lit, all);
}

float hYCov(vec2 p, float s, float px) {
  vec2 d = ySdf2(p / s);
  return 1.0 - smoothstep(-px * 0.6, px * 0.6, min(d.x, d.y) * s);
}

// The radar-ping fronts at radius r: x = sharp line, y = soft wake, z = excitation of the rings.
vec3 hPings(float r, float px) {
  vec3 o = vec3(0.0);
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    if (s <= 0.0) continue;
    float rp = 1.95 * (1.0 - exp(-ag * 2.1));
    float fade = (1.0 - smoothstep(0.55, 1.1, ag)) * (1.0 - smoothstep(1.35, 1.8, rp));
    float d = r - rp;
    o.x += hLine(d, px, 1.5) * fade;
    o.y += (d < 0.0 ? exp(d / 0.07) : exp(-d / (px * 2.5))) * fade;
    o.z += exp(-d * d / 0.0016) * fade;
  }
  return o;
}

// The whole display at point P (sphere units). Premultiplied rgba.
vec4 hud(vec2 P) {
  float px = uPx / uRadius;
  float r = length(P);
  float t = atan(P.y, r < 1e-6 ? 1.0 : P.x) / TAU;
  vec2 par = vec2(sin(uTilt), -sin(uTiltX) * 2.0);
  float e = uEnergy;
  float lock = smoothstep(0.18, 0.45, e);
  float beat = uPulse;
  vec4 S = vec4(0.0);
  bool light = uLight > 0.5;

  vec3 ping = hPings(r, px);
  float exc = 1.0 + ping.z * 2.5 + beat * 0.6;

  // ── Glass panel ──────────────────────────────────────────────────────
  float panel = hFill(r - 0.955, px);
  if (light) {
    hOver(S, mix(vec3(0.93, 0.96, 1.0), vec3(0.86, 0.92, 1.0), smoothstep(0.2, 0.95, r)), panel * 0.8);
  } else {
    vec3 pc = mix(vec3(0.016, 0.026, 0.07), vec3(0.008, 0.02, 0.05), smoothstep(0.0, 0.9, r));
    hOver(S, pc, panel * 0.88);
    S.rgb += H_CYAN * panel * (exp(-(0.955 - r) / 0.09) * 0.06 + exp(-r * r * 3.0) * 0.035);
  }

  // ── Radar sweep (clockwise), a soft trailing wedge with a crisp leading edge ──
  float sweep = fract(uTime * 0.16 + uSwirl * 0.05);
  float behind = fract(t + sweep);
  float wedge = exp(-behind * 6.5) * smoothstep(0.08, 0.3, r) * hFill(r - 0.93, px);
  float lead = hLine(min(behind, 1.0 - behind) * TAU * r, px, 1.2) * smoothstep(0.05, 0.25, r) * hFill(r - 0.93, px);
  hGlow(S, mix(H_CYAN, H_BLUE, 0.3), wedge * 0.16);
  hEmit(S, H_ICE, lead * 0.55);

  // Polar grid: faint range rings and spokes, lit as the sweep passes.
  float lit = 0.25 + exp(-behind * 4.0) * 0.9;
  float rr = fract(r / 0.15 + 0.5) - 0.5;
  float rings = hLine(rr * 0.15, px, 1.0) * step(r, 0.6) * step(0.1, r);
  float sp = fract(t * 12.0 + 0.5) - 0.5;
  float spokes = hLine(sp / 12.0 * TAU * r, px, 1.0) * smoothstep(0.1, 0.2, r) * step(r, 0.6);
  hEmit(S, H_BLUE, (rings + spokes * 0.7) * 0.11 * lit);

  // Blips revealed by the sweep.
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float gen = floor(uTime * 0.07 + hash2(vec2(fi, 2.0)));
    vec2 hb = vec2(hash2(vec2(fi, gen)), hash2(vec2(gen, fi + 7.0)));
    float br = 0.22 + 0.62 * hb.x;
    float ba = hb.y;
    vec2 bp = vec2(cos(ba * TAU), sin(ba * TAU)) * br;
    float bb = exp(-fract(ba + sweep) * 3.5);
    float dd = length(P - bp);
    float dot0 = hFill(dd - px * 1.6, px);
    float ring0 = hLine(dd - 0.022 - (1.0 - bb) * 0.02, px, 1.0);
    vec3 bc = i == 2 ? H_MAG : H_CYAN;
    hEmit(S, bc, (dot0 * 0.9 + ring0 * 0.5) * bb);
    hGlow(S, bc, exp(-dd / 0.02) * 0.25 * bb);
  }

  // ── Rings ────────────────────────────────────────────────────────────
  float base = uSwirl * 0.16;               // shared spin (turns): faster while typing
  float L = uSwirl * 0.21;                  // the phase they lock onto

  // Inner bezel.
  float b0 = hLine(r - 0.605, px, 1.2);
  hEmit(S, H_CYAN, b0 * 0.6 * exc);
  hGlow(S, H_CYAN, exp(-abs(r - 0.605) / 0.012) * 0.08 * exc);

  // Fine tick ring with a mechanical stepping rotation.
  float stepX = uSwirl * 1.6;
  float tickRot = (floor(stepX) + smoothstep(0.65, 1.0, fract(stepX))) / 72.0;
  float tk = hTicks(r, t, 0.625, 0.648, 72.0, tickRot, px);
  float tkM = hTicks(r, t, 0.618, 0.662, 8.0, tickRot, px);
  hEmit(S, H_CYAN, (tk * 0.42 + tkM * 0.85) * exc);

  // Segmented arcs: translucent bands with hairline outlines.
  float rotA = hLock(base + uTime * 0.021 + 0.13, L, 3.0, lock);
  float sA = hSegSd(r, t, 0.69, 0.728, 3.0, 0.78, rotA);
  hGlow(S, mix(H_CYAN, H_VIOLET, 0.25), hFill(sA, px) * 0.12 * exc);
  hEmit(S, mix(H_CYAN, H_VIOLET, 0.25), hLine(sA, px, 1.1) * 0.75 * exc);
  float rotA2 = hLock(base * 0.6 - uTime * 0.032 + 0.41, L, 4.0, lock);
  float sA2 = hSegSd(r, t, 0.738, 0.746, 4.0, 0.42, rotA2);
  hEmit(S, H_VIOLET, hFill(sA2, px) * 0.85 * exc);

  // Dashed data rings (barcode), counter-rotating.
  float rotD = hLock(base * 0.8 - uTime * 0.017, L, 1.0, lock * 0.0);
  float uD = fract((t - rotD) * 120.0);
  float cD = floor(fract(t - rotD) * 120.0);
  float fD = 0.25 + 0.6 * hash2(vec2(cD, 3.0));
  float onD = step(0.32, hash2(vec2(cD, 9.0)));
  float dD = (abs(uD - 0.5) - 0.5 * fD) / 120.0 * TAU * r;
  hEmit(S, H_CYAN, hLine(r - 0.775, px, 1.3) * hFill(dD, px) * onD * 0.55 * exc);
  float rotD2 = base * 1.1 + uTime * 0.011;
  float uD2 = fract((t - rotD2) * 200.0);
  float cD2 = floor(fract(t - rotD2) * 200.0);
  float onD2 = step(0.5, hash2(vec2(cD2, 5.0)));
  float dD2 = (abs(uD2 - 0.5) - 0.3) / 200.0 * TAU * r;
  hEmit(S, H_BLUE, hLine(r - 0.795, px, 1.1) * hFill(dD2, px) * onD2 * 0.4 * exc);

  // Segment counter: a comet of lit blocks that ticks one block forward per keystroke.
  {
    float N = 60.0;
    float sC = hSegSd(r, t, 0.83, 0.862, N, 0.62, 0.0);
    float tc = fract(0.25 - t);
    float idx = floor(tc * N);
    float head = mod(uKicks, N);
    float ageC = mod(head - 1.0 - idx + N * 2.0, N);
    float on = ageC < 20.0 ? pow(1.0 - ageC / 20.0, 1.5) : 0.0;
    float newest = ageC < 0.5 ? uKick : 0.0;
    vec3 cc = mix(H_CYAN, H_MAG, smoothstep(6.0, 18.0, ageC));
    float fillC = hFill(sC, px);
    hEmit(S, H_BLUE, fillC * 0.09);
    hEmit(S, cc, fillC * (on * 0.85 + newest * 1.4) * (1.0 + beat * 0.5));
    hGlow(S, cc, exp(-max(sC, 0.0) / 0.012) * (on * 0.12 + newest * 0.5));
  }

  // Main ring: the brightest line, brand-tinted around its circumference.
  vec3 mainC = mix(H_CYAN, palette(r > 0.0 ? P.x / r : 0.0), 0.45);
  float dm = r - 0.9;
  hEmit(S, mainC, hLine(dm, px, 1.5) * (1.0 + beat * 0.8) * exc);
  hGlow(S, mainC, (exp(-abs(dm) / 0.01) * 0.22 + exp(-abs(dm) / 0.05) * 0.06) * (1.0 + beat * 1.5) * exc);
  // Notches on the main ring at the cardinal points.
  float nT = fract(t * 4.0 + 0.5) - 0.5;
  float notch = hFill(max(abs(nT) / 4.0 * TAU * r - (0.9 - r) * 0.6 - 0.004, max(0.872 - r, r - 0.9)), px);
  hEmit(S, H_ICE, notch * 0.9 * exc);

  // Outer brackets, slowly counter-rotating; violet and magenta accents.
  float rotB = hLock(-base * 0.5 + uTime * 0.012 + 0.125, L * 0.5 + 0.125, 4.0, lock);
  float uB = fract((t - rotB) * 4.0);
  float dBa = (abs(uB - 0.5) - 0.5 * 0.2) / 4.0 * TAU * r;
  float brk = hLine(r - 0.975, px, 1.2) * hFill(dBa, px);
  float capA = abs(abs(uB - 0.5) - 0.1) / 4.0 * TAU * r;
  float caps = hLine(capA, px, 1.2) * hFill(max(0.952 - r, r - 0.975), px);
  vec3 bcol = mix(H_VIOLET, H_MAG, 0.5 + 0.5 * sin(t * TAU * 2.0));
  hEmit(S, bcol, (brk + caps) * 0.8 * exc);
  hGlow(S, bcol, exp(-abs(r - 0.975) / 0.012) * hFill(dBa, px) * 0.1 * exc);

  // Outer dotted ring.
  float uO = fract((t + base * 0.25) * 180.0);
  float dO = length(vec2((uO - 0.5) / 180.0 * TAU * r, r - 1.06));
  hEmit(S, H_BLUE, hFill(dO - px * 0.7, px) * 0.45 * exc);

  // ── Readouts ─────────────────────────────────────────────────────────
  // Spectrum fan, lower left.
  {
    float a0 = 0.6;
    float a1 = 0.69;
    float tt = fract(t);
    if (tt > a0 - 0.01 && tt < a1 + 0.01 && r > 1.0 && r < 1.3) {
      float N = 16.0;
      float cell = (tt - a0) / (a1 - a0) * N;
      float ci = floor(cell);
      float lv = 0.25 + 0.55 * vnoise(vec3(ci * 0.7, uTime * 2.2, 1.0)) + uKick * 0.35 * hash2(vec2(ci, uKicks)) + e * 0.3;
      float len = 0.025 + 0.15 * clamp(lv, 0.0, 1.0);
      float uc = fract(cell);
      float da = (abs(uc - 0.5) - 0.22) / N * (a1 - a0) * TAU * r;
      float dr = max(1.1 - r, r - (1.1 + len));
      float inside = step(0.0, ci) * step(ci, N - 1.0);
      float bar = hFill(max(da, dr), px) * inside;
      vec3 c = mix(H_CYAN, H_VIOLET, smoothstep(1.1, 1.25, r));
      hEmit(S, c, bar * 0.75 * exc);
      float trk = hLine(r - 1.085, px, 1.0) * step(a0, tt) * step(tt, a1);
      hEmit(S, H_CYAN, trk * 0.5);
    }
  }
  // Progress arcs, upper right: fill while forging.
  {
    float a0 = 0.04;
    float a1 = 0.2;
    float tt = fract(t);
    if (tt > a0 - 0.02 && tt < a1 + 0.02 && r > 1.0 && r < 1.2) {
      for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float rc = 1.1 + fi * 0.03;
        float fillP = clamp(0.18 + 0.32 * vnoise(vec3(fi * 3.1, uTime * 0.35, 4.0)) + e * 1.1 + beat * 0.15, 0.0, 1.0);
        float aEnd = a0 + (a1 - a0) * fillP;
        float trackSd = max(a0 - tt, tt - a1) * TAU * r;
        float fillSd = max(a0 - tt, tt - aEnd) * TAU * r;
        float trk = hLine(r - rc, px, 1.0) * hFill(trackSd, px);
        float bar = hFill(abs(r - rc) - px * 1.4, px) * hFill(fillSd, px);
        float capT = hLine((tt - aEnd) * TAU * r, px, 1.2) * hFill(abs(r - rc) - 0.01, px);
        vec3 c = i == 0 ? H_CYAN : i == 1 ? H_VIOLET : H_MAG;
        hEmit(S, c, trk * 0.28 + (bar * 0.85 + capT) * (1.0 + beat * 0.6));
        hGlow(S, c, exp(-abs(r - rc) / 0.008) * hFill(fillSd, px) * 0.12 * (1.0 + beat));
      }
    }
  }
  // Seven-segment keystroke counter, bottom.
  {
    vec2 q = P - vec2(-0.09, -1.17);
    if (q.x > -0.06 && q.x < 0.24 && q.y > -0.03 && q.y < 0.11) {
      float v = mod(uKicks, 1000.0);
      float dw = 0.042;
      float dh = 0.075;
      float lit3 = 0.0;
      float all3 = 0.0;
      for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float dig = i == 0 ? floor(v / 100.0) : i == 1 ? floor(mod(v, 100.0) / 10.0) : mod(v, 10.0);
        vec2 dg = hDigit(q - vec2(fi * 0.064, 0.0), dig, dw, dh, px);
        lit3 = max(lit3, dg.x);
        all3 = max(all3, dg.y);
      }
      hEmit(S, H_BLUE, all3 * 0.12);
      hEmit(S, H_ICE, lit3 * (0.9 + uKick * 0.6));
      hGlow(S, H_CYAN, lit3 * 0.3);
    }
    // Brackets either side of the counter.
    vec2 qb = vec2(abs(P.x), P.y + 1.132);
    float br = hLine(qb.x - 0.155, px, 1.1) * hFill(abs(qb.y) - 0.05, px)
             + hLine(abs(qb.y) - 0.05, px, 1.1) * hFill(abs(qb.x - 0.143) - 0.012, px);
    hEmit(S, H_CYAN, br * 0.6);
  }

  // ── The Y: a scanlined hologram ──────────────────────────────────────
  {
    float ys = 0.82;
    vec2 Py = P - par * 0.018;
    float glitchK = smoothstep(0.42, 0.85, uKick);
    float flick = 1.0 - 0.16 * step(0.93, hash2(vec2(floor(uTime * 17.0), 1.3))) - 0.025 * sin(uTime * 61.0);
    vec4 yv = yFlat(Py, ys, px);
    float fr = px * 1.6 + glitchK * px * 3.0;
    float cL = hYCov(Py + vec2(fr, 0.0), ys, px);
    float cR = hYCov(Py - vec2(fr, 0.0), ys, px);
    float period = max(0.021, px * 3.2);
    float scan = 0.5 + 0.5 * cos(TAU * (Py.y / period - uTime * 0.9));
    float band = exp(-pow((Py.y - (0.55 - fract(uTime * 0.3) * 1.5)) / 0.05, 2.0));
    vec3 yc = yv.rgb * (0.78 + 0.22 * scan) * flick;
    yc = mix(yc, H_ICE, band * 0.35) + yv.rgb * ping.y * 0.5;
    float halo = yFlatGlow(Py, ys, 0.05);
    if (light) {
      hEmit(S, H_MAG, max(cL - yv.a, 0.0) * 0.6);
      hEmit(S, H_CYAN, max(cR - yv.a, 0.0) * 0.6);
      hGlow(S, H_VIOLET, halo * (1.0 - yv.a) * 0.18);
      S = S * (1.0 - yv.a) + vec4(yv.rgb * (0.86 + 0.14 * scan) * yv.a, yv.a);
    } else {
      S.rgb += mix(H_VIOLET, H_CYAN, 0.4) * halo * (1.0 - yv.a) * (0.22 + uPulse * 0.25) * flick;
      S.rgb += H_MAG * max(cL - yv.a, 0.0) * 0.75 + H_CYAN * max(cR - yv.a, 0.0) * 0.75;
      S = S * (1.0 - yv.a) + vec4(yc * yv.a * 1.1, yv.a);
      // The scan band crossing the display.
      S.rgb += H_CYAN * band * 0.05 * panel;
    }
  }

  // ── Radar pings on top ───────────────────────────────────────────────
  hEmit(S, mix(H_ICE, vec3(1.0), 0.4), ping.x * 1.2);
  hGlow(S, H_CYAN, ping.y * 0.22);
  return S;
}

vec4 core(vec2 uv) {
  float px = uPx / uRadius;
  vec2 P = uv / uRadius;
  // Keystroke glitch (~120 ms): horizontal slices tear sideways and the channels split.
  float g = smoothstep(0.42, 0.85, uKick);
  vec4 S;
  if (g > 0.001) {
    float seed = uKicks * 7.31 + floor(uTime * 30.0);
    float b1 = floor(P.y * 7.0 + hash2(vec2(seed, 1.0)) * 7.0);
    float b2 = floor(P.y * 23.0 + hash2(vec2(seed, 2.0)) * 23.0);
    float sh = (hash2(vec2(b1, seed)) - 0.5) * 0.16 * step(0.55, hash2(vec2(b1, seed + 3.0)))
             + (hash2(vec2(b2, seed)) - 0.5) * 0.05 * step(0.7, hash2(vec2(b2, seed + 5.0)));
    vec2 Q = P + vec2(sh * g, 0.0);
    float split = g * (px * 3.0 + 0.012);
    vec4 cR = hud(Q + vec2(split, 0.0));
    vec4 cG = hud(Q);
    vec4 cB = hud(Q - vec2(split, 0.0));
    S = vec4(cR.r, cG.g, cB.b, max(max(cR.a, cG.a), cB.a));
  } else {
    S = hud(P);
  }
  vec3 col = tonemap(S.rgb);
  float a = clamp(max(S.a, hMaxc(col)), 0.0, 1.0);
  col += (hash2(gl_FragCoord.xy + fract(uTime) * 61.0) - 0.5) / 255.0 * a;
  col = clamp(col, vec3(0.0), vec3(a));
  return vec4(col, a);
}
`,
};

