import type { CoreConcept } from "../types";

/**
 * Holo HUD — a flat sci-fi targeting display: hairline rings, ticks, segmented arcs and data
 * rings turning at their own speeds, a trailing radar sweep, and the Y as a scanlined hologram.
 * Typing fires radar pings, glitches the display, ticks the counters and locks the rings together.
 */
export const holo: CoreConcept = {
  id: "holo",
  name: "Holo HUD",
  kind: "2D",
  tagline: "Holographic targeting display",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 2.0,
  frag: /* glsl */ `
const vec3 H_CYAN = vec3(0.10, 0.86, 1.00);
const vec3 H_ICE = vec3(0.72, 0.97, 1.00);
const vec3 H_BLUE = vec3(0.24, 0.50, 1.00);
const vec3 H_VIOLET = vec3(0.60, 0.36, 1.00);
const vec3 H_MAG = vec3(0.96, 0.26, 0.92);

float hLine(float d, float px, float w) { return clamp(0.5 * w + 0.5 - abs(d) / px, 0.0, 1.0); }
float hFill(float sd, float px) { return clamp(0.5 - sd / px, 0.0, 1.0); }
float hMaxc(vec3 c) { return max(max(c.r, c.g), c.b); }
// Light theme: the same hues as deep, saturated ink.
vec3 hInk(vec3 c) { return mix(c * c * 0.62, vec3(0.04, 0.08, 0.34), 0.32); }

// Emissive mark: light on the dark theme, ink on the light theme.
void hEmit(inout vec4 S, vec3 c, float a) {
  if (uLight > 0.5) {
    float k = clamp(a * 1.25, 0.0, 1.0);
    S = S * (1.0 - k) + vec4(hInk(c) * k, k);
  } else {
    S.rgb += c * a;
  }
}
// Soft light: much weaker as ink, so the light theme stays clean.
void hGlow(inout vec4 S, vec3 c, float a) {
  if (uLight > 0.5) {
    float k = clamp(a * 0.3, 0.0, 1.0);
    S = S * (1.0 - k) + vec4(hInk(c) * k, k);
  } else {
    S.rgb += c * a;
  }
}
void hOver(inout vec4 S, vec3 c, float a) { S = S * (1.0 - a) + vec4(c * a, a); }

// Annular sector pattern: N segments each filling 'fill' of its cell, rotated by rot (turns).
float hSegSd(float r, float t, float r0, float r1, float N, float fill, float rot) {
  float u = fract((t - rot) * N);
  float sa = (abs(u - 0.5) - 0.5 * fill) / N * TAU * r;
  return max(sa, max(r0 - r, r - r1));
}
float hTicks(float r, float t, float r0, float r1, float N, float rot, float px) {
  float u = fract((t - rot) * N);
  float d = (u - 0.5) / N * TAU * r;
  return hLine(d, px, 1.15) * hFill(max(r0 - r, r - r1), px);
}
// Phase-lock a ring with N-fold symmetry toward angle L by amount k (smooth, never jumps).
float hLock(float rot, float L, float N, float k) {
  return rot + k * sin(TAU * N * (L - rot)) / (TAU * N);
}

float hSegMask(float d) {
  if (d < 0.5) return 63.0;
  if (d < 1.5) return 6.0;
  if (d < 2.5) return 91.0;
  if (d < 3.5) return 79.0;
  if (d < 4.5) return 102.0;
  if (d < 5.5) return 109.0;
  if (d < 6.5) return 125.0;
  if (d < 7.5) return 7.0;
  if (d < 8.5) return 127.0;
  return 111.0;
}
float hBit(float m, float k) { return mod(floor(m / k + 0.001), 2.0); }
float hSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
// One seven-segment digit in a w x h box (origin bottom-left). Returns (lit, ghost) coverage.
vec2 hDigit(vec2 p, float d, float w, float h, float px) {
  p.x -= p.y * 0.18;
  float m = hSegMask(d);
  float g = w * 0.16;
  float hh = h * 0.5;
  float lit = 0.0;
  float ghost = 0.0;
  float s;
  s = hLine(hSeg(p, vec2(g, h), vec2(w - g, h)), px, 1.4); lit = max(lit, s * hBit(m, 1.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(w, hh + g), vec2(w, h - g)), px, 1.4); lit = max(lit, s * hBit(m, 2.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(w, g), vec2(w, hh - g)), px, 1.4); lit = max(lit, s * hBit(m, 4.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(g, 0.0), vec2(w - g, 0.0)), px, 1.4); lit = max(lit, s * hBit(m, 8.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(0.0, g), vec2(0.0, hh - g)), px, 1.4); lit = max(lit, s * hBit(m, 16.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(0.0, hh + g), vec2(0.0, h - g)), px, 1.4); lit = max(lit, s * hBit(m, 32.0)); ghost = max(ghost, s);
  s = hLine(hSeg(p, vec2(g, hh), vec2(w - g, hh)), px, 1.4); lit = max(lit, s * hBit(m, 64.0)); ghost = max(ghost, s);
  return vec2(lit, ghost);
}

// Signed distance to the flat Y (sphere units) at scale s.
float hYSd(vec2 p, float s) {
  vec2 d = ySdf2(p / s);
  return min(d.x, d.y) * s;
}

// Radar-ping fronts at radius r: x = sharp line, y = soft wake, z = how hard they excite the rings.
vec3 hPings(float r, float px) {
  vec3 o = vec3(0.0);
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    if (s <= 0.0) continue;
    float rp = 1.95 * (1.0 - exp(-ag * 2.1));
    float fade = (1.0 - smoothstep(0.5, 1.1, ag)) * (1.0 - smoothstep(1.3, 1.8, rp));
    float d = r - rp;
    o.x += hLine(d, px, 1.5) * fade;
    o.y += (d < 0.0 ? exp(d / 0.035) : exp(-d / (px * 3.0))) * fade;
    o.z += exp(-d * d / 0.0012) * fade;
  }
  return o;
}

// The whole display at point P (sphere units). Premultiplied rgba.
vec4 hud(vec2 P) {
  float px = uPx / uRadius;
  float r = length(P);
  float t = atan(P.y, r < 1e-6 ? 1.0 : P.x) / TAU;
  float tt = fract(t);
  vec2 par = vec2(sin(uTilt), -sin(uTiltX) * 2.0);
  float e = uEnergy;
  float lock = smoothstep(0.16, 0.42, e);
  float beat = uPulse;
  vec4 S = vec4(0.0);
  bool light = uLight > 0.5;

  vec3 ping = hPings(r, px);

  // Radar sweep (clockwise): angle behind its leading edge, in turns.
  float sweep = fract(uTime * 0.15 + uSwirl * 0.06);
  float behind = fract(t + sweep);
  float sweepLit = exp(-behind * 9.0) * step(r, 0.96);
  float exc = 1.0 + ping.z * 2.6 + beat * 0.7 + sweepLit * 0.5;

  // ── Glass panel ──────────────────────────────────────────────────────
  float panel = hFill(r - 0.955, px);
  float scanP = 0.5 + 0.5 * cos(TAU * (P.y / max(0.016, px * 3.0) - uTime * 0.5));
  if (light) {
    vec3 pc = mix(vec3(0.95, 0.975, 1.0), vec3(0.84, 0.9, 1.0), smoothstep(0.25, 0.95, r));
    hOver(S, pc, panel * 0.85);
  } else {
    vec3 pc = mix(vec3(0.02, 0.034, 0.085), vec3(0.008, 0.016, 0.045), smoothstep(0.0, 0.9, r));
    hOver(S, pc, panel * 0.9);
    S.rgb += H_CYAN * panel * (exp(-(0.955 - r) / 0.07) * 0.07 + exp(-r * r * 3.5) * 0.04) * (0.85 + 0.15 * scanP);
    S.rgb += H_BLUE * panel * (0.012 + beat * 0.025);
  }

  // Sweep: a soft trailing wedge with a crisp leading edge.
  float inR = smoothstep(0.04, 0.3, r) * hFill(r - 0.93, px);
  float wedge = (exp(-behind * 5.0) * 0.8 + exp(-behind * 22.0) * 0.6) * inR;
  float lead = hLine(min(behind, 1.0 - behind) * TAU * r, px, 1.2) * inR;
  hGlow(S, mix(H_BLUE, H_CYAN, exp(-behind * 8.0)), wedge * 0.2);
  hEmit(S, H_ICE, lead * 0.7);

  // Polar grid: faint range rings and spokes, lit as the sweep passes.
  float glit = 0.22 + exp(-behind * 5.0) * 1.2;
  float rr = fract(r / 0.15 + 0.5) - 0.5;
  float rings = hLine(rr * 0.15, px, 1.0) * step(r, 0.6) * step(0.1, r);
  float sp = fract(t * 12.0 + 0.5) - 0.5;
  float spokes = hLine(sp / 12.0 * TAU * r, px, 1.0) * smoothstep(0.1, 0.2, r) * step(r, 0.6);
  hEmit(S, H_BLUE, (rings + spokes * 0.6) * 0.12 * glit);

  // Blips revealed by the sweep.
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float gen = floor(uTime * 0.07 + hash2(vec2(fi, 2.0)));
    vec2 hb = vec2(hash2(vec2(fi, gen)), hash2(vec2(gen, fi + 7.0)));
    float br = 0.24 + 0.6 * hb.x;
    float ba = hb.y;
    vec2 bp = vec2(cos(ba * TAU), sin(ba * TAU)) * br;
    float bb = exp(-fract(ba + sweep) * 3.0);
    float dd = length(P - bp);
    if (dd > 0.08) continue;
    float dot0 = hFill(dd - px * 1.5, px);
    float ring0 = hLine(dd - 0.018 - (1.0 - bb) * 0.025, px, 1.0);
    vec3 bc = i == 2 ? H_MAG : i == 4 ? H_VIOLET : H_CYAN;
    hEmit(S, bc, (dot0 + ring0 * 0.55) * bb);
    hGlow(S, bc, exp(-dd / 0.016) * 0.3 * bb);
  }

  // ── Rings ────────────────────────────────────────────────────────────
  float base = uSwirl * 0.17;               // shared spin (turns): faster while typing

  // Inner bezel.
  float b0 = hLine(r - 0.605, px, 1.2);
  hEmit(S, H_CYAN, b0 * 0.55 * exc);
  hGlow(S, H_CYAN, exp(-abs(r - 0.605) / 0.01) * 0.07 * exc);

  // Fine tick ring with a mechanical stepping rotation.
  float stepX = uSwirl * 1.6;
  float tickRot = (floor(stepX) + smoothstep(0.65, 1.0, fract(stepX))) / 72.0;
  float tk = hTicks(r, t, 0.626, 0.646, 72.0, tickRot, px);
  float tkM = hTicks(r, t, 0.618, 0.664, 8.0, tickRot, px);
  hEmit(S, H_CYAN, (tk * 0.38 + tkM * 0.9) * exc);

  // Segmented arcs: translucent bands with hairline outlines; they lock together while typing.
  vec3 arcC = mix(H_CYAN, H_VIOLET, 0.3);
  float rotA = hLock(base + uTime * 0.019 + 0.13, base, 3.0, lock);
  float sA = hSegSd(r, t, 0.69, 0.726, 3.0, 0.8, rotA);
  hGlow(S, arcC, hFill(sA, px) * (0.1 + lock * 0.06) * exc);
  hEmit(S, arcC, hLine(sA, px, 1.1) * 0.8 * exc);
  float rotA2 = hLock(-base * 0.4 - uTime * 0.027 + 0.41, base, 3.0, lock);
  float sA2 = hSegSd(r, t, 0.736, 0.744, 3.0, 0.3, rotA2);
  hEmit(S, H_MAG, hFill(sA2, px) * 0.85 * exc);
  hGlow(S, H_MAG, exp(-max(sA2, 0.0) / 0.01) * 0.12 * exc);

  // Dashed data rings (barcode), counter-rotating.
  float rotD = hLock(base * 0.7 - uTime * 0.017, base, 1.0, lock * 0.5);
  float uD = fract((t - rotD) * 120.0);
  float cD = floor(fract(t - rotD) * 120.0);
  float fD = 0.25 + 0.6 * hash2(vec2(cD, 3.0));
  float onD = step(0.32, hash2(vec2(cD, 9.0)));
  float dD = (abs(uD - 0.5) - 0.5 * fD) / 120.0 * TAU * r;
  hEmit(S, H_CYAN, hLine(r - 0.774, px, 1.3) * hFill(dD, px) * onD * 0.55 * exc);
  float rotD2 = -base * 1.2 + uTime * 0.011;
  float uD2 = fract((t - rotD2) * 200.0);
  float cD2 = floor(fract(t - rotD2) * 200.0);
  float onD2 = step(0.5, hash2(vec2(cD2, 5.0)));
  float dD2 = (abs(uD2 - 0.5) - 0.3) / 200.0 * TAU * r;
  hEmit(S, H_BLUE, hLine(r - 0.794, px, 1.1) * hFill(dD2, px) * onD2 * 0.45 * exc);

  // Segment counter: a comet of lit blocks that ticks one block forward per keystroke.
  {
    float N = 60.0;
    float sC = hSegSd(r, t, 0.83, 0.86, N, 0.62, 0.0);
    float idx = floor(fract(0.25 - t) * N);
    float head = mod(uKicks, N);
    float ageC = mod(head - 1.0 - idx + N * 2.0, N);
    float on = ageC < 22.0 ? pow(1.0 - ageC / 22.0, 1.4) : 0.0;
    float newest = ageC < 0.5 ? uKick : 0.0;
    vec3 cc = mix(H_ICE, H_CYAN, smoothstep(0.0, 4.0, ageC));
    cc = mix(cc, H_VIOLET, smoothstep(6.0, 20.0, ageC));
    float fillC = hFill(sC, px);
    hEmit(S, H_BLUE, fillC * 0.1);
    hEmit(S, cc, fillC * (on * 0.9 + newest * 1.5) * (1.0 + beat * 0.5));
    hGlow(S, cc, exp(-max(sC, 0.0) / 0.01) * (on * 0.14 + newest * 0.6));
  }

  // Main ring: the brightest line, brand-tinted around its circumference.
  vec3 mainC = mix(H_CYAN, palette(r > 0.0 ? P.x / r : 0.0), 0.5);
  float dm = r - 0.9;
  float mainK = (1.0 + beat * 1.0) * exc;
  hEmit(S, mix(mainC, vec3(1.0), 0.25), hLine(dm, px, 1.5) * mainK);
  hGlow(S, mainC, (exp(-abs(dm) / 0.008) * 0.25 + exp(-abs(dm) / 0.045) * 0.06) * mainK);
  float nT = fract(t * 4.0 + 0.5) - 0.5;
  float notch = hFill(max(abs(nT) / 4.0 * TAU * r - (0.9 - r) * 0.6 - 0.004, max(0.874 - r, r - 0.9)), px);
  hEmit(S, H_ICE, notch * 0.9 * exc);

  // Outer brackets, slowly counter-rotating; violet and magenta accents.
  float rotB = hLock(-base * 0.5 + uTime * 0.012 + 0.125, base + 0.125, 4.0, lock);
  float uB = fract((t - rotB) * 4.0);
  float dBa = (abs(uB - 0.5) - 0.1) / 4.0 * TAU * r;
  float brk = hLine(r - 0.975, px, 1.2) * hFill(dBa, px);
  float capA = abs(abs(uB - 0.5) - 0.1) / 4.0 * TAU * r;
  float caps = hLine(capA, px, 1.2) * hFill(max(0.952 - r, r - 0.975), px);
  vec3 bcol = mix(H_VIOLET, H_MAG, 0.5 + 0.5 * sin(t * TAU * 2.0));
  hEmit(S, bcol, (brk + caps) * 0.85 * exc);
  hGlow(S, bcol, exp(-abs(r - 0.975) / 0.01) * hFill(dBa, px) * 0.1 * exc);

  // Outer dotted ring.
  float uO = fract((t + base * 0.25) * 180.0);
  float dO = length(vec2((uO - 0.5) / 180.0 * TAU * r, r - 1.06));
  hEmit(S, H_BLUE, hFill(dO - px * 0.7, px) * 0.5 * exc);

  // Lock chevrons: slide in and light up as the rings lock.
  {
    float q = fract(tt * 4.0 - 0.5) - 0.5;
    vec2 cp = vec2(r - (1.17 - lock * 0.05), q / 4.0 * TAU * r);
    float chev = hLine(abs(cp.y) * 0.8 + cp.x, px, 1.3) * step(abs(cp.y), 0.03);
    vec3 cc = mix(H_BLUE, H_ICE, lock);
    hEmit(S, cc, chev * (0.35 + lock * 0.9) * (1.0 + beat * 0.6));
    hGlow(S, H_CYAN, chev * lock * 0.35);
  }

  // ── Readouts ─────────────────────────────────────────────────────────
  // Spectrum fan, lower left.
  if (tt > 0.59 && tt < 0.7 && r > 1.0 && r < 1.3) {
    float a0 = 0.6;
    float a1 = 0.69;
    float N = 16.0;
    float cell = (tt - a0) / (a1 - a0) * N;
    float ci = floor(cell);
    float lv = 0.22 + 0.55 * vnoise(vec3(ci * 0.7, uTime * 2.2, 1.0)) + uKick * 0.4 * hash2(vec2(ci, uKicks)) + e * 0.3 + beat * 0.2;
    float len = 0.02 + 0.15 * clamp(lv, 0.0, 1.0);
    float da = (abs(fract(cell) - 0.5) - 0.22) / N * (a1 - a0) * TAU * r;
    float dr = max(1.1 - r, r - (1.1 + len));
    float bar = hFill(max(da, dr), px) * step(0.0, ci) * step(ci, N - 1.0);
    vec3 c = mix(H_CYAN, H_VIOLET, smoothstep(1.1, 1.24, r));
    hEmit(S, c, bar * 0.8 * exc);
    hEmit(S, H_CYAN, hLine(r - 1.085, px, 1.0) * step(a0, tt) * step(tt, a1) * 0.5);
  }
  // Progress arcs, upper right: they fill while forging.
  if (tt > 0.02 && tt < 0.22 && r > 1.0 && r < 1.2) {
    float a0 = 0.04;
    float a1 = 0.2;
    for (int i = 0; i < 3; i++) {
      float fi = float(i);
      float rc = 1.1 + fi * 0.03;
      float fillP = clamp(0.16 + 0.3 * vnoise(vec3(fi * 3.1, uTime * 0.35, 4.0)) + e * 1.15 + beat * 0.12, 0.0, 1.0);
      float aEnd = a0 + (a1 - a0) * fillP;
      float trackSd = max(a0 - tt, tt - a1) * TAU * r;
      float fillSd = max(a0 - tt, tt - aEnd) * TAU * r;
      float trk = hLine(r - rc, px, 1.0) * hFill(trackSd, px);
      float bar = hFill(abs(r - rc) - px * 1.4, px) * hFill(fillSd, px);
      float capT = hLine((tt - aEnd) * TAU * r, px, 1.2) * hFill(abs(r - rc) - 0.01, px);
      vec3 c = i == 0 ? H_CYAN : i == 1 ? H_VIOLET : H_MAG;
      hEmit(S, c, trk * 0.28 + (bar * 0.85 + capT) * (1.0 + beat * 0.7));
      hGlow(S, c, exp(-abs(r - rc) / 0.007) * hFill(fillSd, px) * 0.13 * (1.0 + beat));
    }
  }
  // Seven-segment keystroke counter, bottom.
  {
    vec2 q = P - vec2(-0.09, -1.17);
    if (q.x > -0.06 && q.x < 0.24 && q.y > -0.03 && q.y < 0.11) {
      float v = mod(uKicks, 1000.0);
      float lit3 = 0.0;
      float ghost3 = 0.0;
      for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float dig = i == 0 ? floor(v / 100.0) : i == 1 ? floor(mod(v, 100.0) / 10.0) : mod(v, 10.0);
        vec2 dg = hDigit(q - vec2(fi * 0.064, 0.0), dig, 0.042, 0.075, px);
        lit3 = max(lit3, dg.x);
        ghost3 = max(ghost3, dg.y);
      }
      hEmit(S, H_BLUE, ghost3 * 0.12);
