import type { CoreConcept } from "../types";

/**
 * Singularity — a black hole with a gravitationally lensed accretion disk (photon paths are bent
 * by a compact Schwarzschild integrator), Doppler-beamed and streaked, with the Y floating in front
 * of the event-horizon shadow. Typing spins the disk up, drops infalling streaks and flare clumps.
 */
export const singularity: CoreConcept = {
  id: "singularity",
  name: "Singularity",
  kind: "3D",
  tagline: "Black hole with an accretion disk",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 2.3,
  frag: /* glsl */ `
// Units inside the black hole: the Schwarzschild radius is 1.
const float S_INC = 0.25;     // camera elevation above the disk plane (rad)
const float S_RIN = 2.9;      // disk inner edge
const float S_ROUT = 8.8;     // disk outer edge
const float S_BC = 2.598;     // critical impact parameter = shadow radius
const float S_RS = 0.2;       // sphere units per Schwarzschild radius
const float S_R0 = 11.0;      // rays are integrated inside this sphere

float gLatest = 10.0;
float gAct = 0.0;
void sTypingState() {
  gLatest = 10.0;
  gAct = 0.0;
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    if (s <= 0.0) continue;
    gLatest = min(gLatest, ag);
    gAct += smoothstep(0.0, 0.12, ag) * (1.0 - smoothstep(0.35, 0.75, ag));
  }
}

// Disk colour by temperature q: 0 = cool outer bands (pink/magenta) .. 1 = white-hot inner edge.
vec3 sRamp(float q) {
  vec3 c = mix(vec3(0.55, 0.05, 0.36), vec3(1.0, 0.27, 0.65), smoothstep(0.0, 0.16, q));
  c = mix(c, vec3(0.9, 0.22, 0.98), smoothstep(0.14, 0.34, q));
  c = mix(c, vec3(0.55, 0.30, 1.0), smoothstep(0.32, 0.52, q));
  c = mix(c, vec3(0.22, 0.47, 1.0), smoothstep(0.5, 0.68, q));
  c = mix(c, vec3(0.10, 0.85, 1.0), smoothstep(0.66, 0.84, q));
  return mix(c, vec3(0.88, 0.98, 1.0), smoothstep(0.84, 1.0, q));
}

float sWrap(float a) { return a - TAU * floor((a + PI) / TAU); }

// Emission (rgb) and opacity (a) where a ray travelling along v crosses the disk plane at pc.
vec4 sDisk(vec3 pc, vec3 v, float clock) {
  float rc = length(pc.xz);
  if (rc > S_ROUT || rc < 1.0) return vec4(0.0);
  float x = (rc - S_RIN) / (S_ROUT - S_RIN);
  float phi = atan(pc.z, pc.x);

  // Relativistic beaming: the disk turns so its left side rushes toward the camera.
  vec3 u = vec3(pc.z, 0.0, -pc.x) / rc;
  float beta = min(sqrt(0.5 / max(rc - 1.0, 0.5)), 0.6);
  float gam = 1.0 / sqrt(1.0 - beta * beta);
  float cosT = dot(u, -v / max(length(v), 1e-5));
  float g = sqrt(max(1.0 - 1.0 / rc, 0.02)) / (gam * (1.0 - beta * cosT));
  float beam = clamp(g * g * g, 0.05, 6.0);

  // Turbulent streaks in differential rotation; two cross-fading layers so they never over-wind.
  float om = pow(S_RIN / max(rc, 1.0), 1.5);
  float st = 0.0;
  float w2 = 0.0;
  for (int k = 0; k < 2; k++) {
    float fk = float(k);
    float cyc = clock / 2.4 + fk * 0.5;
    float ph = fract(cyc);
    float cid = floor(cyc);
    float w = 1.0 - abs(2.0 * ph - 1.0);
    float ang = phi + om * ph * 2.4 + cid * 2.3 + fk * 1.1;
    vec3 q = vec3(cos(ang) * 1.5, sin(ang) * 1.5, rc * 2.2 + cid * 3.7 + fk * 5.0);
    float n = ridged(q);
    st += w * (n - 0.5);
    w2 += w * w;
  }
  float streak = clamp(0.5 + st / sqrt(max(w2, 1e-3)) * 1.2, 0.0, 1.0);
  float fine = 0.72 + 0.28 * sin(rc * 21.0 + streak * 4.0);

  float inner = smoothstep(S_RIN - 0.04, S_RIN + 0.3, rc);
  float outer = 1.0 - smoothstep(0.42, 1.0, x);
  float prof = pow(S_RIN / rc, 1.8) * inner * outer;
  float edge = exp(-pow((rc - S_RIN - 0.16) / 0.2, 2.0));
  float plunge = smoothstep(1.2, S_RIN, rc) * (1.0 - inner) * 0.12;
  float I = (prof * (0.18 + 1.25 * streak * streak) * fine + edge * 0.85 + plunge) * beam * (1.0 + gAct * 0.12);
  float q = clamp(1.0 - x * 1.1 + log2(max(g, 0.05)) * 0.55 + edge * 0.25, 0.0, 1.0);
  vec3 col = sRamp(q) * I;
  float a = clamp(I * 0.8, 0.0, 0.93);

  // Keystrokes: a hot flare clump orbiting through the disk, and a streak spiralling into the hole.
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    if (s <= 0.0) continue;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    float sd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
    // Flare clump.
    float rk = 3.4 + sd * 1.9;
    float pk = sd * 19.0 - pow(S_RIN / rk, 1.5) * ag * 3.4;
    vec2 ck = vec2(cos(pk), sin(pk)) * rk;
    vec2 dv = pc.xz - ck;
    vec2 rad = ck / rk;
    vec2 tng = vec2(rad.y, -rad.x);
    float dr = dot(dv, rad);
    float dt = dot(dv, tng);
    float tail = dt < 0.0 ? 1.4 : 0.35;
    float blob = exp(-(dr * dr / 0.05 + dt * dt / (tail * tail)));
    float flare = blob * smoothstep(0.0, 0.08, ag) * (1.0 - smoothstep(0.7, 1.55, ag)) * 3.0 * beam;
    col += mix(vec3(0.75, 0.97, 1.0), vec3(1.0), blob) * flare;
    a = max(a, clamp(flare * 0.6, 0.0, 0.95));
    // Infalling streak.
    float fa = clamp(ag / 1.3, 0.0, 1.0);
    float rh = 1.0 + 7.6 * pow(1.0 - fa, 1.35);
    float rTail = rh * 1.55 + 0.6;
    if (rc > rh - 0.2 && rc < rTail) {
      float phs = sd * 31.0 - 2.3 * log(8.6 / rc);
      float dd = sWrap(phi - phs) * rc;
      float along = smoothstep(rTail, rh + 0.15, rc) * smoothstep(rh - 0.2, rh + 0.05, rc);
      float thread = exp(-dd * dd / 0.012) * along;
      float sI = thread * (1.0 - smoothstep(0.82, 1.0, fa)) * smoothstep(0.0, 0.06, ag) * 2.6 * beam;
      col += vec3(0.8, 0.96, 1.0) * sI;
      a = max(a, clamp(sI * 0.5, 0.0, 0.9));
    }
  }
  return vec4(col, a);
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float pxW = uPx / R;
  float pxRs = pxW / S_RS;
  bool light = uLight > 0.5;
  sTypingState();
  float forge = smoothstep(0.25, 0.4, uEnergy);
  float rP = length(P);

  // Spin: uSwirl (faster while forging) plus a jump-free ratchet on every keystroke.
  float kx = clamp(gLatest / 0.26, 0.0, 1.0);
  float clock = uSwirl * 2.0 + (uKicks - 1.0 + 0.6 * kx + 0.4 * (1.0 - (1.0 - kx) * (1.0 - kx))) * 0.8;

  // Camera: orthographic rays, slightly above the disk plane.
  vec3 nO = vec3(0.0, sin(S_INC), cos(S_INC));
  vec3 upV = vec3(0.0, cos(S_INC), -sin(S_INC));
  vec3 rtV = vec3(1.0, 0.0, 0.0);
  vec2 sc = P / S_RS;
  float b = length(sc);

  vec3 E = vec3(0.0);
  float T = 1.0;
  float Tca = 1.0;
  float captured = 0.0;
  float orbit = 0.0;
  vec3 vEsc = -nO;
  if (b < S_R0 - 0.01) {
    vec3 x = nO * sqrt(S_R0 * S_R0 - b * b) + rtV * sc.x + upV * sc.y;
    vec3 v = -nO;
    vec3 hv = cross(x, v);
    float h2 = dot(hv, hv);
    float r = length(x);
    vec3 a = -1.5 * h2 * x / (r * r * r * r * r);
    float rMin = r;
    bool done = false;
    for (int i = 0; i < 48; i++) {
      float dt = max(0.12 * r, 0.06);
      vec3 xn = x + v * dt + 0.5 * a * dt * dt;
      float rn = length(xn);
      vec3 an = -1.5 * h2 * xn / max(rn * rn * rn * rn * rn, 1e-4);
      vec3 vn = v + 0.5 * (a + an) * dt;
      if (x.y * xn.y < 0.0) {
        float f = x.y / (x.y - xn.y);
        vec4 dk = sDisk(mix(x, xn, f), mix(v, vn, f), clock);
        E += T * dk.rgb;
        T *= 1.0 - dk.a;
      }
      x = xn;
      v = vn;
      a = an;
      r = rn;
      if (r < rMin) { rMin = r; Tca = T; }
      if (r < 1.03) { captured = 1.0; done = true; break; }
      if (r > S_R0 + 0.5 && dot(x, v) > 0.0) { done = true; break; }
      if (T < 0.015) { done = true; break; }
    }
    if (!done) orbit = 1.0;
    vEsc = v / max(length(v), 1e-5);
  }

  // Shadow: analytic, anti-aliased edge; rays that were still circling count as captured.
  float shadow = 1.0 - smoothstep(S_BC - pxRs * 0.8, S_BC + pxRs * 0.8, b);
  float hole = max(shadow, max(captured, orbit) * smoothstep(S_BC + pxRs * 3.0, S_BC + pxRs * 1.0, b));

  // Photon ring: razor thin at the shadow edge, beamed brighter on the approaching side.
  float side = sc.x / max(b, 1e-4);
  float ringBeam = 1.25 - side * 0.55;
  float ringK = (1.0 + uKick * 2.2 + gAct * 0.35 + uPulse * 0.4) * ringBeam;
  float dB = (b - S_BC) / pxRs;
  float ring = exp(-dB * dB / 1.1) * 1.4 + exp(-max(b - S_BC, 0.0) / (pxRs * 2.5 + 0.06)) * step(S_BC, b) * 0.35;
  vec3 ringCol = mix(vec3(0.8, 0.96, 1.0), vec3(1.0, 0.6, 0.95), smoothstep(-0.3, 1.0, side));
  E += ringCol * ring * ringK * Tca;
  E += ringCol * orbit * (1.0 - shadow) * 0.6 * ringK;

  // Lensed sky behind the hole: a faint haze and drifting stars that smear into arcs near the ring.
  vec3 sky = vec3(0.0);
  if (!light && captured < 0.5 && orbit < 0.5) {
    vec3 dv = vEsc + nO;
    vec2 bg = sc + vec2(dot(dv, rtV), dot(dv, upV)) * 14.0;
    float fadeS = 1.0 - smoothstep(1.3, 2.05, rP);
    float hz = exp(-length(bg) * 0.32);
    sky += mix(vec3(0.3, 0.2, 0.9), vec3(0.75, 0.25, 0.85), smoothstep(-6.0, 6.0, bg.x)) * hz * 0.16;
    vec2 sp = bg * 1.15 + vec2(uTime * 0.12, 0.0);
    vec2 cell = floor(sp);
    vec2 h = vec2(hash2(cell), hash2(cell + 17.3));
    float sd = length(fract(sp) - (0.2 + 0.6 * h));
    float star = step(0.72, hash2(cell + 5.1)) * exp(-sd * sd / 0.0025) * (0.4 + 0.6 * hash2(cell + 9.7));
    sky += mix(vec3(0.7, 0.85, 1.0), vec3(1.0, 0.75, 0.95), h.x) * star * 0.9;
    sky *= fadeS * T;
  }

  // Relativistic jets along the poles while forging (they flash on each beat).
  vec3 jetC = vec3(0.0);
  float J = forge * (0.18 + 1.3 * uPulse);
  if (J > 0.002) {
    float ay = abs(P.y);
    float wid = 0.01 + ay * 0.045;
    float core0 = exp(-pow(P.x / (wid * 0.28 + pxW * 0.7), 2.0));
    float sheath = exp(-pow(P.x / wid, 2.0));
    float along = smoothstep(0.05, 0.3, ay) * (1.0 - smoothstep(1.0, 1.95, ay));
    float knots = 0.55 + 0.45 * sin(ay * 16.0 - uTime * 13.0);
    float lower = P.y < 0.0 ? (1.0 - hole) * T : 1.0;
    vec3 jc = mix(vec3(0.85, 0.97, 1.0), vec3(0.55, 0.3, 1.0), smoothstep(0.0, 0.8, abs(P.x) / max(wid, 1e-4)));
    jc = mix(jc, vec3(0.95, 0.3, 0.9), smoothstep(0.6, 1.8, ay) * 0.6);
    jetC = jc * (core0 * 1.4 + sheath * 0.35) * along * knots * J * lower;
  }

  // Compose the black hole (premultiplied).
  vec3 col;
  float alpha;
  if (light) {
    float m = max(max(E.r, E.g), E.b);
    vec3 hue = E / max(m, 1e-4);
    vec3 ink = mix(hue * hue * 0.78, hue * 0.55, 0.4);
    float aE = 1.0 - exp(-m * 1.7);
    col = ink * aE;
    alpha = aE + (1.0 - aE) * hole;
    float mj = max(max(jetC.r, jetC.g), jetC.b);
    float aj = clamp(mj * 0.8, 0.0, 0.85);
    col = col * (1.0 - aj) + (jetC / max(mj, 1e-4)) * 0.5 * aj;
    alpha = alpha + (1.0 - alpha) * aj;
  } else {
    col = tonemap(E + sky + jetC);
    float m = max(max(col.r, col.g), col.b);
    alpha = clamp(max(max(1.0 - T, hole), m), 0.0, 1.0);
    col = min(col, vec3(alpha));
  }

  // The Y floats in front of the shadow, glowing, rim-lit by the disk below.
  vec2 yo = vec2(0.0, 0.035);
  float ys = 0.72;
  if (abs(P.x) < 0.5 && abs(P.y - yo.y) < 0.36) {
    vec3 ro = vec3(P - yo, 3.0);
    vec3 rd = vec3(0.0, 0.0, -1.0);
    vec3 pB; float sB; float armB;
    float minD = yTrace(ro, rd, 6.0, ys, pB, sB, armB);
    float cov = yCoverage(minD, pxW);
    if (minD < 0.04) {
      vec3 yb = yColor(pB.xy, armB);
      float halo = exp(-max(minD, 0.0) * 55.0) * (1.0 - cov);
      vec3 hc = yb * halo * (0.35 + uKick * 0.3 + uPulse * 0.25);
      if (cov > 0.0) {
        vec3 yc = yShade(pB, armB, rd, 1.1 + uKick * 0.35 + uPulse * 0.3);
        vec3 nv = yToView() * yNormal(pB);
        float rim = pow(1.0 - abs(nv.z), 1.5);
        vec3 diskL = mix(vec3(0.55, 0.95, 1.0), vec3(1.0, 0.45, 0.9), smoothstep(-0.6, 0.6, nv.x));
        yc += diskL * rim * (0.35 + 0.65 * smoothstep(0.2, -0.8, nv.y)) * 0.9;
        yc = tonemap(yc);
        col = col * (1.0 - cov) + yc * cov;
        alpha = alpha + (1.0 - alpha) * cov;
      }
      if (!light) {
        col += hc * (1.0 - cov);
        alpha = max(alpha, min(max(max(col.r, col.g), col.b), 1.0));
      }
    }
  }
  // Dither.
  col += (hash2(gl_FragCoord.xy + fract(uTime) * 37.0) - 0.5) / 255.0 * alpha;
  col = clamp(col, vec3(0.0), vec3(alpha));
  return vec4(col, alpha);
}
`,
};

