import type { CoreConcept } from "../types";

/**
 * Prism Gem — an analytic round-brilliant (73 facet planes intersected per ray, no marching) with
 * internal reflections, per-channel IOR fire, facet-synced starburst glints and the Y suspended
 * inside as a luminous inclusion. Typing jolts it round a facet at a time and throws rainbow rays.
 */
export const prism: CoreConcept = {
  id: "prism",
  name: "Prism Gem",
  kind: "3D",
  tagline: "Faceted crystal with dispersion",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 2.0,
  frag: /* glsl */ `
const float G_SIZE = 0.9;      // girdle radius in sphere units
const float G_TABLE = 0.33;    // table height (girdle radius = 1)
const vec2 G_R45 = vec2(0.70710678, 0.70710678);
const vec2 G_R22 = vec2(0.92387953, 0.38268343);
const vec3 G_KEY = vec3(-0.3939, 0.6190, 0.6794);
const vec3 G_CYL = vec3(0.6634, 0.2296, 0.7121);
const vec3 G_MAGL = vec3(0.1521, -0.6590, 0.7366);

float gLatest = 10.0;
float gAct = 0.0;
void gTypingState() {
  gLatest = 10.0;
  gAct = 0.0;
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    if (s <= 0.0) continue;
    gLatest = min(gLatest, ag);
    gAct += smoothstep(0.0, 0.12, ag) * (1.0 - smoothstep(0.35, 0.75, ag));
  }
}
float gEaseBack(float x) {
  float u = x - 1.0;
  return 1.0 + 2.70158 * u * u * u + 1.70158 * u * u;
}

// ── Convex brilliant: intersect a ray with every facet plane ───────────────
float gTin;
float gTin2;
float gTout;
vec3 gNin;
vec3 gNin2;
vec3 gNout;
void gPlane(vec3 o, vec3 d, vec3 n, float dd) {
  float den = dot(n, d);
  float num = dd - dot(n, o);
  if (den < -1e-7) {
    float t = num / den;
    if (t > gTin) { gTin2 = gTin; gNin2 = gNin; gTin = t; gNin = n; }
    else if (t > gTin2) { gTin2 = t; gNin2 = n; }
  } else if (den > 1e-7) {
    float t = num / den;
    if (t < gTout) { gTout = t; gNout = n; }
  } else if (num < 0.0) {
    gTin = 1e9;
  }
}
// A ring of N facets around the axis: normal (h cos a, ny, h sin a), stepping a by the rotation rt.
void gFam(vec3 o, vec3 d, float N, vec2 cs, vec2 rt, float h, float ny, float dd) {
  for (int k = 0; k < 16; k++) {
    if (float(k) >= N) break;
    gPlane(o, d, vec3(h * cs.x, ny, h * cs.y), dd);
    cs = vec2(cs.x * rt.x - cs.y * rt.y, cs.x * rt.y + cs.y * rt.x);
  }
}
void gHit(vec3 o, vec3 d) {
  gTin = -1e9;
  gTin2 = -1e9;
  gTout = 1e9;
  gNin = vec3(0.0, 1.0, 0.0);
  gNin2 = gNin;
  gNout = gNin;
  gPlane(o, d, vec3(0.0, 1.0, 0.0), G_TABLE);                                          // table
  gFam(o, d, 8.0, vec2(1.0, 0.0), G_R45, 0.5664, 0.8241, 0.5870);                      // bezel
  gFam(o, d, 8.0, vec2(0.92387953, 0.38268343), G_R45, 0.3665, 0.9304, 0.4903);       // star
  gFam(o, d, 16.0, vec2(0.98078528, 0.19509032), G_R22, 0.6691, 0.7431, 0.6877);      // upper girdle
  gFam(o, d, 16.0, vec2(1.0, 0.0), G_R22, 1.0, 0.0, 1.0);                              // girdle
  gFam(o, d, 8.0, vec2(1.0, 0.0), G_R45, 0.6521, -0.7582, 0.6521);                     // pavilion
  gFam(o, d, 16.0, vec2(0.98078528, 0.19509032), G_R22, 0.6810, -0.7323, 0.6810);     // lower girdle
}

// Studio around the stone: dark, with a white key, cyan and magenta lights and a strip softbox.
vec3 gEnv(vec3 w) {
  bool light = uLight > 0.5;
  vec3 c = light ? mix(vec3(0.62, 0.62, 0.74), vec3(0.93, 0.93, 0.98), smoothstep(-0.7, 0.8, w.y))
                 : mix(vec3(0.008, 0.008, 0.024), vec3(0.03, 0.022, 0.075), smoothstep(-0.7, 0.8, w.y));
  float kd = max(dot(w, G_KEY), 0.0);
  c += vec3(1.0, 0.98, 1.0) * (pow(kd, 120.0) * 9.0 + pow(kd, 12.0) * 0.25);
  c += vec3(0.1, 0.86, 1.0) * pow(max(dot(w, G_CYL), 0.0), 36.0) * 3.2;
  c += vec3(0.95, 0.24, 0.95) * pow(max(dot(w, G_MAGL), 0.0), 30.0) * 3.0;
  c += vec3(0.5, 0.32, 1.0) * pow(max(w.z, 0.0), 3.0) * (light ? 0.1 : 0.35);
  float strip = smoothstep(0.035, 0.0, abs(w.y - 0.36 - w.x * 0.15)) * smoothstep(0.0, 0.45, w.z) * smoothstep(0.8, 0.35, abs(w.x + 0.1));
  c += vec3(0.85, 0.92, 1.0) * strip * 3.2;
  float strip2 = smoothstep(0.03, 0.0, abs(w.x - 0.52)) * smoothstep(0.1, 0.5, w.z) * smoothstep(0.6, 0.1, abs(w.y + 0.1));
  c += vec3(0.6, 0.45, 1.0) * strip2 * 2.4;
  if (light) {
    float dark = smoothstep(0.05, 0.0, abs(w.y + 0.25 + w.x * 0.2)) * smoothstep(0.0, 0.3, w.z);
    c *= 1.0 - dark * 0.85;
  }
  return c;
}

vec3 gSpectrum(float t) {
  float h = clamp(t, 0.0, 1.0) * 0.8;
  return clamp(vec3(abs(h * 6.0 - 3.0) - 1.0, 2.0 - abs(h * 6.0 - 2.0), 2.0 - abs(h * 6.0 - 4.0)), 0.0, 1.0);
}

// Four-point starburst (plus faint diagonals) at c, rotated by a.
float gStar(vec2 p, vec2 c, float a, float len, float px) {
  vec2 q = p - c;
  float cs = cos(a), sn = sin(a);
  q = vec2(cs * q.x - sn * q.y, sn * q.x + cs * q.y);
  vec2 aq = abs(q);
  float w = px * 0.9;
  float arms = exp(-aq.y / w) * exp(-aq.x / len) + exp(-aq.x / w) * exp(-aq.y / len);
  vec2 dq = vec2(aq.x + aq.y, abs(aq.x - aq.y)) * 0.7071;
  arms += (exp(-dq.y / w) * exp(-dq.x / (len * 0.45))) * 0.45;
  float core0 = exp(-dot(q, q) / (px * px * 6.0 + 0.0004));
  return arms * 0.85 + core0;
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float pxW = uPx / R;
  float rP = length(P);
  bool light = uLight > 0.5;
  gTypingState();
  float forge = smoothstep(0.25, 0.4, uEnergy);
  float beat = uPulse;

  // Orientation: face-up stone tipped toward the viewer; spins slowly, ratchets a facet per key,
  // and wobbles on the keystroke spring.
  float kstep = uKicks - 1.0 + gEaseBack(clamp(gLatest / 0.26, 0.0, 1.0));
  float spin = uSwirl * 0.45 + kstep * (TAU / 16.0) + uImpulse * 0.35;
  float ax = 1.22 + uImpulse * 0.2 + sin(uTime * 0.37) * 0.05;
  float az = 0.22 + uImpulse * 0.12 + sin(uTime * 0.23 + 1.0) * 0.06;
  mat3 M = rotZ(az) * rotX(ax) * rotY(spin);
  mat3 Mi = rotY(-spin) * rotX(-ax) * rotZ(-az);

  vec3 col = vec3(0.0);
  float alpha = 0.0;
  float cov = 0.0;
  if (rP < 1.25) {
    vec3 o = Mi * vec3(P, 3.0) / G_SIZE;
    vec3 d = Mi * vec3(0.0, 0.0, -1.0);
    gHit(o, d);
    vec3 n1 = gNin;
    vec3 n2 = gNin2;
    vec3 nO = gNout;
    float tIn = gTin;
    float tIn2 = gTin2;
    float tOut = gTout;
    // Silhouette coverage from how fast the entry/exit planes converge across the screen.
    vec3 ex = Mi * vec3(1.0, 0.0, 0.0);
    vec3 ey = Mi * vec3(0.0, 1.0, 0.0);
    float di = dot(n1, d);
    float dO = dot(nO, d);
    vec2 gr = vec2(dot(n1, ex) / di - dot(nO, ex) / dO, dot(n1, ey) / di - dot(nO, ey) / dO) / G_SIZE;
    float sil = (tOut - tIn) / max(length(gr), 1e-3);
    cov = clamp(sil / pxW + 0.5, 0.0, 1.0);
    if (cov > 0.0) {
      vec3 p = o + d * tIn;
      // Facet edges on the entry surface: crisp 1px lines.
      float d2 = dot(n2, d);
      vec2 ge = vec2(dot(n1, ex) / di - dot(n2, ex) / d2, dot(n1, ey) / di - dot(n2, ey) / d2) / G_SIZE;
      float edgeD = (tIn - tIn2) / max(length(ge), 1e-3) / pxW;
      float edge = exp(-edgeD * edgeD * 1.2) * step(-1e8, tIn2);

      float cosI = clamp(-di, 0.0, 1.0);
      float F = 0.17 + 0.83 * pow(1.0 - cosI, 5.0);
      vec3 front = gEnv(M * reflect(d, n1)) * F;

      // Inside: refract in, then up to two internal bounces; dispersion on every exit.
      vec3 dir = refract(d, n1, 1.0 / 2.42);
      vec3 q = p - n1 * 1e-4;
      vec3 thr = vec3(1.0 - F);
      vec3 inner = vec3(0.0);
      float path = 0.0;
      bool stopped = false;
      vec3 absorb = vec3(0.16, 0.3, 0.03);
      float ys = 0.62;
      float emisY = 1.25 + forge * beat * 1.4 + uKick * 0.3;
      for (int b = 0; b < 3; b++) {
        gHit(q, dir);
        float seg = max(gTout, 0.0);
        vec3 nx = gNout;
        // The Y inclusion along this segment (world space; it hangs upright at the centre).
        vec3 pB; float sB; float armB;
        float minD = yTrace(G_SIZE * (M * q), M * dir, seg * G_SIZE, ys, pB, sB, armB);
        float yc = yCoverage(minD, pxW * 1.6);
        vec3 tint = exp(-(path + 0.5 * seg) * absorb * (light ? 0.6 : 1.0));
        if (minD < 0.032) {
          vec3 yb = yColor(pB.xy, armB);
          float hk = 1.0 - clamp(minD / 0.032, 0.0, 1.0);
          inner += thr * yb * hk * hk * hk * (1.0 - yc) * (0.6 + forge * beat * 0.8) * tint;
          if (yc > 0.0) {
            vec3 ycol = yShade(pB, armB, M * dir, emisY);
            inner += thr * ycol * yc * tint;
