// A ring of N facets around the axis: normal (h cos a, ny, h sin a), stepping a by the rotation rt.
void gFam(vec3 o, vec3 d, float N, vec2 cs, vec2 rt, float h, float ny, float dd) {
  for (int k = 0; k < 16; k++) {
    if (float(k) >= N) break;
    gPlane(o, d, vec3(h * cs.x, ny, h * cs.y), dd);
    cs = vec2(cs.x * rt.x - cs.y * rt.y, cs.x * rt.y + cs.y * rt.x);
  }
}
void gHit(vec3 o, vec3 d) {
  gTin = -1e9;
  gTin2 = -1e9;
  gTout = 1e9;
  gNin = vec3(0.0, 1.0, 0.0);
  gNin2 = gNin;
  gNout = gNin;
