// Studio around the stone: a ring of neon softbox panels in brand hues separated by dark gaps
// (so facets alternate bright and dark), a sharp white key and a dim violet room behind.
vec3 gEnv(vec3 w) {
  bool light = uLight > 0.5;
  float az = atan(w.y, abs(w.x) + abs(w.y) < 1e-6 ? 1.0 : w.x);
  vec3 c = light ? mix(vec3(0.56, 0.56, 0.7), vec3(0.92, 0.92, 0.98), smoothstep(-0.7, 0.8, w.y))
                 : mix(vec3(0.006, 0.006, 0.02), vec3(0.03, 0.022, 0.075), smoothstep(-0.7, 0.8, w.y));
  float sec = fract(az / TAU * 5.0 + 0.08);
