  c += (light ? pc * pc * 0.9 : pc * 1.6) * panel * band * grad;
  float kd = max(dot(w, G_KEY), 0.0);
  c += vec3(1.0) * (pow(kd, 220.0) * 12.0 + pow(kd, 40.0) * 0.3);
