299	  float uB = fract((t - rotB) * 4.0);
300	  float dBa = (abs(uB - 0.5) - 0.1) / 4.0 * TAU * r;
301	  float brk = hLine(r - 0.975, px, 1.2) * hFill(dBa, px);
302	  float capA = abs(abs(uB - 0.5) - 0.1) / 4.0 * TAU * r;
303	  float caps = hLine(capA, px, 1.2) * hFill(max(0.952 - r, r - 0.975), px);
304	  vec3 bcol = mix(H_VIOLET, H_MAG, 0.5 + 0.5 * sin(t * TAU * 2.0));
305	  hEmit(S, bcol, (brk + caps) * 0.85 * exc);
306	  hGlow(S, bcol, exp(-abs(r - 0.975) / 0.01) * hFill(dBa, px) * 0.1 * exc);
307	
308	  // Outer dotted ring.
309	  float uO = fract((t + uSwirl * 0.04) * 180.0);
310	  float dO = length(vec2((uO - 0.5) / 180.0 * TAU * r, r - 1.06));
311	  hEmit(S, H_BLUE, hFill(dO - px * 0.7, px) * 0.5 * exc);
312	
313	  // Lock chevrons: slide in and light up as the rings lock.
314	  {
315	    float q = fract(tt * 4.0 - 0.5) - 0.5;
316	    vec2 cp = vec2(r - (1.17 - lock * 0.05), q / 4.0 * TAU * r);
317	    float chev = hLine(abs(cp.y) * 0.8 + cp.x, px, 1.3) * step(abs(cp.y), 0.03) * (1.0 - step(abs(tt - 0.75), 0.1));
318	    vec3 cc = mix(H_BLUE, H_ICE, lock);
319	    hEmit(S, cc, chev * (0.35 + lock * 0.9) * (1.0 + beat * 0.6));
320	    hGlow(S, H_CYAN, chev * lock * 0.35);
321	  }
322	
323	  // ── Readouts ─────────────────────────────────────────────────────────
324	  // Spectrum fan, lower left.
325	  if (tt > 0.59 && tt < 0.7 && r > 1.0 && r < 1.3) {
326	    float a0 = 0.6;
327	    float a1 = 0.69;
328	    float N = 16.0;
329	    float cell = (tt - a0) / (a1 - a0) * N;
330	    float ci = floor(cell);
331	    float lv = 0.22 + 0.55 * vnoise(vec3(ci * 0.7, uTime * 2.2, 1.0)) + uKick * 0.4 * hash2(vec2(ci, uKicks)) + act * 0.25 + e * 0.3 + beat * 0.2;
332	    float len = 0.02 + 0.15 * clamp(lv, 0.0, 1.0);
333	    float da = (abs(fract(cell) - 0.5) - 0.22) / N * (a1 - a0) * TAU * r;
334	    float dr = max(1.1 - r, r - (1.1 + len));
335	    float bar = hFill(max(da, dr), px) * step(0.0, ci) * step(ci, N - 1.0);
336	    vec3 c = mix(H_CYAN, H_VIOLET, smoothstep(1.1, 1.24, r));
337	    hEmit(S, c, bar * 0.8 * exc);
338	    hEmit(S, H_CYAN, hLine(r - 1.085, px, 1.0) * step(a0, tt) * step(tt, a1) * 0.5);
339	  }
340	  // Progress arcs, upper right: they fill while forging.
341	  if (tt > 0.02 && tt < 0.22 && r > 1.0 && r < 1.2) {
342	    float a0 = 0.04;
343	    float a1 = 0.2;
344	    for (int i = 0; i < 3; i++) {
345	      float fi = float(i);
346	      float rc = 1.1 + fi * 0.03;
347	      float fillP = clamp(0.16 + 0.3 * vnoise(vec3(fi * 3.1, uTime * 0.35, 4.0)) + e * 1.15 + beat * 0.12, 0.0, 1.0);
348	      float aEnd = a0 + (a1 - a0) * fillP;
349	      float trackSd = max(a0 - tt, tt - a1) * TAU * r;
350	      float fillSd = max(a0 - tt, tt - aEnd) * TAU * r;
351	      float trk = hLine(r - rc, px, 1.0) * hFill(trackSd, px);
352	      float bar = hFill(abs(r - rc) - px * 1.4, px) * hFill(fillSd, px);
353	      float capT = hLine((tt - aEnd) * TAU * r, px, 1.2) * hFill(abs(r - rc) - 0.01, px);
354	      vec3 c = i == 0 ? H_CYAN : i == 1 ? H_VIOLET : H_MAG;
355	      hEmit(S, c, trk * 0.28 + (bar * 0.85 + capT) * (1.0 + beat * 0.7));
356	      hGlow(S, c, exp(-abs(r - rc) / 0.007) * hFill(fillSd, px) * 0.13 * (1.0 + beat));
357	    }
358	  }
359	  // Seven-segment keystroke counter, bottom.
360	  {
361	    vec2 q = P - vec2(-0.09, -1.17);
362	    if (q.x > -0.06 && q.x < 0.24 && q.y > -0.03 && q.y < 0.11) {
363	      float v = mod(uKicks, 1000.0);
364	      float lit3 = 0.0;
365	      float ghost3 = 0.0;
366	      for (int i = 0; i < 3; i++) {
367	        float fi = float(i);
368	        float dig = i == 0 ? floor(v / 100.0) : i == 1 ? floor(mod(v, 100.0) / 10.0) : mod(v, 10.0);
369	        vec2 dg = hDigit(q - vec2(fi * 0.064, 0.0), dig, 0.042, 0.075, px);
370	        lit3 = max(lit3, dg.x);
371	        ghost3 = max(ghost3, dg.y);
372	      }
373	      hEmit(S, H_BLUE, ghost3 * 0.12);
374	      hEmit(S, H_ICE, lit3 * (0.9 + uKick * 0.6));
375	      hGlow(S, H_CYAN, lit3 * 0.3);
376	    }
377	    vec2 qb = vec2(abs(P.x), P.y + 1.132);
378	    float br = hLine(qb.x - 0.155, px, 1.1) * hFill(abs(qb.y) - 0.05, px)
379	             + hLine(abs(qb.y) - 0.05, px, 1.1) * hFill(abs(qb.x - 0.143) - 0.012, px);
380	    hEmit(S, H_CYAN, br * 0.6);
381	  }
382	
383	  return S;
384	}
