386	// The Y: a scanlined hologram floating just above the display. Kept out of hud() (and out of any
387	// branch) so its texture lookups don't force the glitch branch to run every frame.
388	vec4 hYLayer(vec4 S, vec2 P, float glitchK) {
389	  float px = uPx / uRadius;
390	  float r = length(P);
391	  bool light = uLight > 0.5;
392	  vec2 par = vec2(sin(uTilt), -sin(uTiltX) * 2.0);
393	  float ys = 0.84;
394	  vec2 Py = P - par * 0.02;
395	  float flick = 1.0 - 0.18 * step(0.94, hash2(vec2(floor(uTime * 17.0), 1.3))) - 0.03 * sin(uTime * 61.0);
396	  vec4 yv = yFlat(Py, ys, px);
397	  float sd = hYSd(Py, ys);
398	  float fr = px * 1.8 + glitchK * (px * 2.0 + 0.007);
399	  float cL = 1.0 - smoothstep(-px * 0.6, px * 0.6, hYSd(Py + vec2(fr, 0.0), ys));
400	  float cR = 1.0 - smoothstep(-px * 0.6, px * 0.6, hYSd(Py - vec2(fr, 0.0), ys));
401	  // Echo: a faint offset copy that drifts and flickers, like an unstable projection.
402	  float echoOff = 0.014 + 0.01 * sin(uTime * 1.3);
403	  float cE = 1.0 - smoothstep(-px * 0.6, px * 0.6, hYSd(Py - vec2(0.0, echoOff), ys));
404	  float period = max(0.019, px * 3.4);
405	  float scan = 0.5 + 0.5 * cos(TAU * (Py.y / period - uTime * 0.9));
406	  float bq = (Py.y - (0.6 - fract(uTime * 0.28) * 1.6)) / 0.045;
407	  float band = exp(-bq * bq);
408	  float rim = exp(-max(-sd, 0.0) / (px * 1.6 + 0.004));
409	  float hk = 1.0 - clamp(sd / 0.04, 0.0, 1.0);
410	  float halo = hk * hk * (1.0 - yv.a);
411	  vec3 ping = hPings(r, px);
412	  float wake = ping.y;
413	  float panel = hFill(r - 0.955, px);
414	  if (light) {
415	    hEmit(S, H_MAG, max(cL - yv.a, 0.0) * 0.55);
416	    hEmit(S, H_CYAN, max(cR - yv.a, 0.0) * 0.55);
417	    hGlow(S, H_VIOLET, halo * 0.35);
418	    vec3 yc = yv.rgb * (0.8 + 0.2 * scan) * mix(1.0, 0.75, rim);
419	    S = S * (1.0 - yv.a) + vec4(yc * yv.a, yv.a);
420	  } else {
421	    vec3 yc = yv.rgb * (0.66 + 0.34 * scan) * flick;
422	    yc = mix(yc, H_ICE * 1.15, rim * 0.55);
423	    yc += H_ICE * band * 0.35 + yv.rgb * wake * 0.6;
424	    S.rgb += mix(H_VIOLET, H_CYAN, 0.5) * halo * (0.3 + uPulse * 0.3 + uKick * 0.2) * flick;
425	    S.rgb += mix(H_CYAN, H_BLUE, 0.4) * max(cE - yv.a, 0.0) * 0.16 * flick;
426	    S.rgb += H_MAG * max(cL - yv.a, 0.0) * 0.85 + H_CYAN * max(cR - yv.a, 0.0) * 0.85;
427	    S = S * (1.0 - yv.a * 0.92) + vec4(yc * yv.a * 1.15, yv.a * 0.92);
428	    S.rgb += H_CYAN * band * 0.06 * panel;
429	  }
430	  // Radar pings on top; mid-glitch their red and blue split apart.
431	  float split = glitchK * (px * 2.5 + 0.009);
432	  float pR = hPings(length(P + vec2(split, 0.0)), px).x;
433	  float pB = hPings(length(P - vec2(split, 0.0)), px).x;
434	  vec3 pc = mix(H_ICE, vec3(1.0), 0.4);
435	  vec3 pingC = vec3(pc.r * pR, pc.g * ping.x, pc.b * pB);
436	  S.rgb += pingC * 1.25 * (1.0 - uLight);
437	  float kp = clamp(max(max(pR, pB), ping.x) * 1.25, 0.0, 1.0) * uLight;
438	  S = S * (1.0 - kp) + vec4(hInk(H_CYAN) * kp, kp);
439	  hGlow(S, H_CYAN, ping.y * 0.14);
440	  return S;
441	}
442	
443	vec4 core(vec2 uv) {
444	  float px = uPx / uRadius;
445	  vec2 P = uv / uRadius;
446	  hTypingState();
447	  // Keystroke glitch (~120 ms): horizontal slices tear sideways and the channels split.
448	  float g = smoothstep(0.42, 0.85, uKick);
449	  float seed = uKicks * 7.31 + floor(uTime * 30.0);
450	  float b1 = floor(P.y * 7.0 + hash2(vec2(seed, 1.0)) * 7.0);
451	  float b2 = floor(P.y * 23.0 + hash2(vec2(seed, 2.0)) * 23.0);
452	  float sh = (hash2(vec2(b1, seed)) - 0.5) * 0.12 * step(0.62, hash2(vec2(b1, seed + 3.0)))
453	           + (hash2(vec2(b2, seed)) - 0.5) * 0.04 * step(0.72, hash2(vec2(b2, seed + 5.0)));
454	  vec2 Q = P + vec2(sh * g, 0.0);
455	  // The display is evaluated once (re-running it per channel triples the compile time); torn
456	  // slices drop to a single channel pair instead, and the Y and pings split for real.
457	  vec4 S = hud(Q);
458	  float torn = step(0.0001, abs(sh));
459	  vec3 sliceTint = hash2(vec2(b1 + b2, seed + 9.0)) < 0.5 ? vec3(1.0, 0.3, 1.0) : vec3(0.25, 1.0, 1.0);
460	  S.rgb *= mix(vec3(1.0), sliceTint, torn * g * 0.85 * (1.0 - uLight));
461	  S = hYLayer(S, Q, g);
462	  vec3 col = tonemap(S.rgb);
463	  float a = clamp(max(S.a, hMaxc(col)), 0.0, 1.0);
464	  col += (hash2(gl_FragCoord.xy + fract(uTime) * 61.0) - 0.5) / 255.0 * a;
465	  col = clamp(col, vec3(0.0), vec3(a));
466	  return vec4(col, a);
467	}
468	`,
469	};
