140	
141	vec4 core(vec2 uv) {
142	  float R = uRadius;
143	  vec2 P = uv / R;
144	  float pxW = uPx / R;
145	  float pxRs = pxW / S_RS;
146	  bool light = uLight > 0.5;
147	  sTypingState();
148	  float forge = smoothstep(0.25, 0.4, uEnergy);
149	  float rP = length(P);
150	
151	  // Spin: uSwirl (faster while forging) plus a jump-free ratchet on every keystroke.
152	  float kx = clamp(gLatest / 0.26, 0.0, 1.0);
153	  float clock = uSwirl * 2.0 + (uKicks - 1.0 + 0.6 * kx + 0.4 * (1.0 - (1.0 - kx) * (1.0 - kx))) * 0.8;
154	
155	  // Camera: orthographic rays, slightly above the disk plane.
156	  vec3 nO = vec3(0.0, sin(S_INC), cos(S_INC));
157	  vec3 upV = vec3(0.0, cos(S_INC), -sin(S_INC));
158	  vec3 rtV = vec3(1.0, 0.0, 0.0);
159	  vec2 sc = P / S_RS;
160	  float b = length(sc);
161	
162	  vec3 E = vec3(0.0);
163	  float T = 1.0;
164	  float Tca = 1.0;
165	  float captured = 0.0;
166	  float orbit = 0.0;
167	  // Far from the hole a ray can't reach the disk: bend it analytically (weak-field 2/b) instead.
168	  vec3 vEsc = -nO - (rtV * sc.x + upV * sc.y) / max(b * b, 1e-3) * 2.0;
169	  if (b < S_ROUT + 0.5) {
170	    vec3 x = nO * sqrt(S_R0 * S_R0 - b * b) + rtV * sc.x + upV * sc.y;
171	    vec3 v = -nO;
172	    vec3 hv = cross(x, v);
173	    float h2 = dot(hv, hv);
174	    float r = length(x);
175	    vec3 a = -1.5 * h2 * x / (r * r * r * r * r);
176	    float rMin = r;
177	    bool done = false;
178	    for (int i = 0; i < 48; i++) {
179	      float dt = max(0.16 * r, 0.05);
180	      vec3 xn = x + v * dt + 0.5 * a * dt * dt;
181	      float rn = length(xn);
182	      vec3 an = -1.5 * h2 * xn / max(rn * rn * rn * rn * rn, 1e-4);
183	      vec3 vn = v + 0.5 * (a + an) * dt;
184	      if (x.y * xn.y < 0.0) {
185	        float f = x.y / (x.y - xn.y);
186	        vec4 dk = sDisk(mix(x, xn, f), mix(v, vn, f), clock);
187	        E += T * dk.rgb;
188	        T *= 1.0 - dk.a;
189	      }
190	      x = xn;
191	      v = vn;
192	      a = an;
193	      r = rn;
194	      if (r < rMin) { rMin = r; Tca = T; }
195	      if (r < 1.03) { captured = 1.0; done = true; break; }
196	      if (r > S_ROUT + 0.4 && dot(x, v) > 0.0) { done = true; break; }
197	      if (T < 0.015) { done = true; break; }
198	    }
199	    if (!done) orbit = 1.0;
200	    vEsc = v / max(length(v), 1e-5);
201	  }
202	
203	  // Shadow: analytic, anti-aliased edge; rays that were still circling count as captured.
204	  float shadow = 1.0 - smoothstep(S_BC - pxRs * 0.8, S_BC + pxRs * 0.8, b);
205	  float hole = max(shadow, max(captured, orbit) * smoothstep(S_BC + pxRs * 3.0, S_BC + pxRs * 1.0, b));
206	
207	  // Photon ring: razor thin at the shadow edge, beamed brighter on the approaching side.
208	  float side = sc.x / max(b, 1e-4);
209	  float ringBeam = 1.25 - side * 0.55;
210	  float swallow = 0.0;
211	  for (int k = 0; k < 4; k++) {
212	    float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
213	    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
214	    float sq = (ag - 1.22) / 0.07;
215	    swallow += step(0.0001, s) * exp(-sq * sq);
216	  }
217	  float ringK = (1.0 + uKick * 2.2 + swallow * 1.6 + gAct * 0.35 + uPulse * 0.4) * ringBeam;
218	  float dB = (b - S_BC) / pxRs;
219	  float ring = exp(-dB * dB / 0.7) * 1.25 + exp(-max(dB, 0.0) / 2.5) * step(0.0, dB) * 0.22;
220	  vec3 ringCol = mix(vec3(0.8, 0.96, 1.0), vec3(1.0, 0.6, 0.95), smoothstep(-0.3, 1.0, side));
221	  E += ringCol * ring * ringK * Tca;
222	  E += ringCol * orbit * (1.0 - shadow) * 0.3 * ringK;
223	
224	  // Lensed sky behind the hole: a faint haze and drifting stars that smear into arcs near the ring.
225	  vec3 sky = vec3(0.0);
226	  if (!light && captured < 0.5 && orbit < 0.5) {
227	    vec3 dv = vEsc + nO;
228	    vec2 bg = sc + vec2(dot(dv, rtV), dot(dv, upV)) * 5.0;
229	    float fadeS = 1.0 - smoothstep(1.3, 2.05, rP);
230	    float hz = exp(-length(bg) * 0.45);
231	    sky += mix(vec3(0.3, 0.2, 0.9), vec3(0.75, 0.25, 0.85), smoothstep(-6.0, 6.0, bg.x)) * hz * 0.1;
232	    vec2 sp = bg * 1.15 + vec2(uTime * 0.12, 0.0);
233	    vec2 cell = floor(sp);
234	    vec2 h = vec2(hash2(cell), hash2(cell + 17.3));
235	    float sd = length(fract(sp) - (0.2 + 0.6 * h));
236	    float star = step(0.8, hash2(cell + 5.1)) * exp(-sd * sd / 0.0012) * (0.3 + 0.7 * hash2(cell + 9.7));
237	    sky += mix(vec3(0.7, 0.85, 1.0), vec3(1.0, 0.75, 0.95), h.x) * star * 0.8;
238	    sky *= fadeS * T;
239	  }
240	
241	  // Relativistic jets along the poles while forging (they flash on each beat).
242	  vec3 jetC = vec3(0.0);
243	  float J = forge * (0.55 + 2.2 * uPulse);
244	  if (J > 0.002) {
245	    float ay = abs(P.y);
246	    float y0 = S_BC * S_RS * 0.92;
247	    float wid = 0.022 + max(ay - y0, 0.0) * 0.1;
248	    float cq = P.x / (wid * 0.2 + pxW * 0.9);
249	    float shq = P.x / wid;
250	    float core0 = exp(-cq * cq);
251	    float sheath = exp(-shq * shq) + exp(-abs(P.x) / (wid * 2.5)) * 0.25;
252	    float reach = 1.4 + uPulse * 0.55;
253	    float along = smoothstep(y0, y0 + 0.1, ay) * (1.0 - smoothstep(reach * 0.45, reach, ay)) * (1.0 - smoothstep(1.55, 2.0, ay));
254	    float knots = 0.6 + 0.4 * sin(ay * 22.0 - uTime * 17.0);
